config.hooks/hooks.json:
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "mcp__cockroachdb-toolbox__cockroachdb-execute-sql",
        "hooks": [
          {
            "type": "command",
            "command": "python3 -c 'import sys, os, runpy; p = os.path.normpath(r\"${CLAUDE_PLUGIN_ROOT}/scripts/validate-sql.py\"); p = (\"\\\\?\\\\\" + p) if os.name == \"nt\" else p; runpy.run_path(p, run_name=\"__main__\")'; exit 0",
            "timeout": 10
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Write|Edit|MultiEdit",
        "hooks": [
          {
            "type": "command",
            "command": "python3 -c 'import sys, os, runpy; p = os.path.normpath(r\"${CLAUDE_PLUGIN_ROOT}/scripts/check-sql-files.py\"); p = (\"\\\\?\\\\\" + p) if os.name == \"nt\" else p; runpy.run_path(p, run_name=\"__main__\")'; exit 0",
            "timeout": 15
          }
        ]
      }
    ]
  }
}

config..mcp.json:
{
  "mcpServers": {
    "cockroachdb-toolbox": {
      "command": "toolbox",
      "args": ["--config", "${CLAUDE_PLUGIN_ROOT}/tools.yaml", "--stdio"],
      "env": {
        "COCKROACHDB_HOST": "${COCKROACHDB_HOST}",
        "COCKROACHDB_PORT": "${COCKROACHDB_PORT}",
        "COCKROACHDB_USER": "${COCKROACHDB_USER}",
        "COCKROACHDB_PASSWORD": "${COCKROACHDB_PASSWORD}",
        "COCKROACHDB_DATABASE": "${COCKROACHDB_DATABASE}",
        "COCKROACHDB_SSLMODE": "${COCKROACHDB_SSLMODE}"
      }
    },
    "cockroachdb-toolbox-http": {
      "type": "http",
      "url": "http://127.0.0.1:5000/mcp",
      "_comment": "SSE transport — run 'toolbox --config tools.yaml' first, then connect via this URL"
    },
    "cockroachdb-cloud": {
      "type": "http",
      "url": "https://cockroachlabs.cloud/mcp",
      "headers": {
        "mcp-cluster-id": "${COCKROACHDB_CLUSTER_ID}"
      }
    }
  }
}
